  "content": "import sys
import types

import attr


class TestClosureCellRewrite:
    def test_rewrite_on_py38(self):
        """
        Regression test for issue #538: ensure that closure cell rewriting
        works on Python 3.8 where CodeType takes a posonlyargcount argument.
        """
        # Create a slotted class with a method that uses super() to
        # trigger closure cell rewriting.
        @attr.s(slots=True)
        class Base:
            def method(self):
                return 42

        @attr.s(slots=True)
        class Derived(Base):
            def method(self):
                return super().method()

        d = Derived()
        assert d.method() == 42
